import{_ as i,I as n,c as o,o as e,a3 as a,b as s,w as r,a as d,J as E,a4 as c}from"./chunks/framework.yHbjT2zn.js";const m=JSON.parse('{"title":"엔터프라이즈 HITL 거버넌스 및 승인 콘솔","description":"AI의 자율성을 보장하면서도 기업 시스템의 안정성을 확보하기 위한 Human-In-The-Loop(HITL) 아키텍트 승인 콘솔, DDL 검증 게이트, 2단계 인증 및 비상 킬스위치(Kill-Switch)를 설명합니다.","frontmatter":{"title":"엔터프라이즈 HITL 거버넌스 및 승인 콘솔","description":"AI의 자율성을 보장하면서도 기업 시스템의 안정성을 확보하기 위한 Human-In-The-Loop(HITL) 아키텍트 승인 콘솔, DDL 검증 게이트, 2단계 인증 및 비상 킬스위치(Kill-Switch)를 설명합니다.","head":[["meta",{"name":"keywords","content":"SyncVerse, HITL, Human-in-the-loop, 엔터프라이즈 거버넌스, DDL 승인, 2단계 인증, OTP, Kill-Switch, 아키텍트 검토"}],["meta",{"property":"og:title","content":"SyncVerse: 엔터프라이즈 HITL 거버넌스 및 승인 콘솔"}],["meta",{"property":"og:description","content":"인간 아키텍트의 1-Click 승인 체계로 시스템 변경 안정성을 확보하는 엔터프라이즈 거버넌스"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/syncverse/hitl-governance.html"}]],"sort":6},"headers":[],"relativePath":"syncverse/hitl-governance.md","filePath":"ko/syncverse/hitl-governance.md","lastUpdated":1787437782000}'),A={name:"syncverse/hitl-governance.md"};function D(h,t,B,g,C,f){const l=n("Mermaid");return e(),o("div",null,[t[1]||(t[1]=a('<h1 id="엔터프라이즈-hitl-거버넌스-및-승인-콘솔" tabindex="-1">엔터프라이즈 HITL 거버넌스 및 승인 콘솔 <a class="header-anchor" href="#엔터프라이즈-hitl-거버넌스-및-승인-콘솔" aria-label="Permalink to “엔터프라이즈 HITL 거버넌스 및 승인 콘솔”">​</a></h1><p>AI 에이전트가 데이터베이스 스키마(DDL)를 임의로 변경하거나, 검증되지 않은 코드를 상용 환경에 배포하는 위험을 방지해야 합니다.</p><p>SyncVerse는 <strong>&quot;코드 생성과 테스트는 AI가 신속히 지원하되, 아키텍처 결정과 배포는 시스템 아키텍트가 최종 승인한다&quot;</strong>는 <strong>HITL (Human-In-The-Loop)</strong> 거버넌스 모델을 채택하고 있습니다.</p><hr><h2 id="_1-ai와-사람의-역할-분담-매트릭스-r-r" tabindex="-1">1. AI와 사람의 역할 분담 매트릭스 (R&amp;R) <a class="header-anchor" href="#_1-ai와-사람의-역할-분담-매트릭스-r-r" aria-label="Permalink to “1. AI와 사람의 역할 분담 매트릭스 (R&amp;R)”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">운영 단계</th><th style="text-align:left;">AI 에이전트 그룹이 수행하는 작업</th><th style="text-align:left;">시스템 아키텍트 (사람)가 수행하는 작업</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>01. 요구사항 분석</strong></td><td style="text-align:left;">자연어 지시 해석, 영향도 분석, 태스크 분해</td><td style="text-align:left;">목표와 요구사항을 자연어로 제시</td></tr><tr><td style="text-align:left;"><strong>02. 소스 수정 &amp; DDL</strong></td><td style="text-align:left;">작업 브랜치 생성, 코드 Diff 및 마이그레이션 DDL 작성</td><td style="text-align:left;"><em>(개입 없음 - AI가 자율 수행)</em></td></tr><tr><td style="text-align:left;"><strong>03. 무인 QA &amp; 자가치유</strong></td><td style="text-align:left;">자동 빌드, E2E 리그레션 테스트, 에러 로그 기반 자가 패치</td><td style="text-align:left;"><em>(개입 없음 - AI가 자율 수행)</em></td></tr><tr><td style="text-align:left;"><strong>04. 검토 및 승인 게이트</strong></td><td style="text-align:left;">변경 요약 리포트, ERD 변경 다이어그램, Diff 시각화 제공</td><td style="text-align:left;"><strong>제안된 코드 Diff와 DDL의 적합성 검토 후 승인/반려 결정</strong></td></tr><tr><td style="text-align:left;"><strong>05. 상용 배포 &amp; 감사</strong></td><td style="text-align:left;">Blue/Green 무중단 배포, Saga 트랜잭션 커밋, 감사 이력 영속화</td><td style="text-align:left;">비상 상황 시 긴급 정지(Kill-Switch) 트리거</td></tr></tbody></table><hr><h2 id="_2-hitl-승인-콘솔의-핵심-기능" tabindex="-1">2. HITL 승인 콘솔의 핵심 기능 <a class="header-anchor" href="#_2-hitl-승인-콘솔의-핵심-기능" aria-label="Permalink to “2. HITL 승인 콘솔의 핵심 기능”">​</a></h2><p>중앙 관제탑 웹 콘솔의 <strong>[HITL 승인 대시보드]</strong>에서는 아키텍트가 신속하게 변경사항을 검토할 수 있도록 시각적 도구를 제공합니다.</p>',9)),(e(),s(c,null,{default:r(()=>[E(l,{id:"mermaid-92",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Review%20%5B%22HITL%20%EC%8A%B9%EC%9D%B8%20%EC%BD%98%EC%86%94%20%ED%99%94%EB%A9%B4%22%5D%0A%20%20%20%20%20%20%20%20R1%5B%22Side-by-Side%20%EC%86%8C%EC%8A%A4%EC%BD%94%EB%93%9C%20Diff%20%EB%B7%B0%EC%96%B4%22%5D%0A%20%20%20%20%20%20%20%20R2%5B%22Before%2FAfter%20DB%20ERD%20%EC%8B%9C%EA%B0%81%ED%99%94%22%5D%0A%20%20%20%20%20%20%20%20R3%5B%22SyncETA%20%EB%AC%B4%EC%9D%B8%20QA%20%ED%86%B5%EA%B3%BC%20%EC%A6%9D%EC%A0%81%20%EB%A6%AC%ED%8F%AC%ED%8A%B8%22%5D%0A%20%20%20%20%20%20%20%20R4%5B%22%EC%9E%90%EA%B0%80%EC%B9%98%EC%9C%A0(Self-Healing)%20%EC%8B%A4%ED%96%89%20%EC%9D%B4%EB%A0%A5%20%ED%83%80%EC%9E%84%EB%9D%BC%EC%9D%B8%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Review%20--%3E%20Choice%7B%22%EC%95%84%ED%82%A4%ED%85%8D%ED%8A%B8%EC%9D%98%20%EA%B2%B0%EC%A0%95%22%7D%0A%20%20%20%20Choice%20--%3E%7C%22Approve%20(%EC%8A%B9%EC%9D%B8)%22%7C%20Deploy%5B%22%EB%AC%B4%EC%A4%91%EB%8B%A8%20%EC%83%81%EC%9A%A9%20%EB%B0%B0%ED%8F%AC%20%ED%8A%B8%EB%A6%AC%EA%B1%B0%22%5D%0A%20%20%20%20Choice%20--%3E%7C%22Reject%20(%EB%B0%98%EB%A0%A4)%22%7C%20Feedback%5B%22AI%20%EC%BD%94%EB%94%A9%20%EC%97%90%EC%9D%B4%EC%A0%84%ED%8A%B8%EC%97%90%20%EC%88%98%EC%A0%95%20%ED%94%BC%EB%93%9C%EB%B0%B1%20%EC%A0%84%EB%8B%AC%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<ol><li><strong>Side-by-Side 코드 Diff 뷰어</strong>: AI가 수정한 소스코드가 기존 파일과 어떻게 다른지 대조</li><li><strong>ERD 마이그레이션 시각화</strong>: 테이블 추가/수정 DDL이 전체 DB 관계도에 미치는 영향을 그래픽으로 표현</li><li><strong>QA 테스트 증적 뷰어</strong>: SyncETA가 실행한 모든 테스트 케이스의 통과 여부 및 실행 시간 확인</li><li><strong>반려 시 피드백 프롬프트 주입</strong>: 반려 시 보완 지시사항을 입력하면 에이전트가 즉시 재수정 작업 착수</li></ol><hr><h2 id="_3-엔터프라이즈-안전장치-security-guardrails" tabindex="-1">3. 엔터프라이즈 안전장치 (Security Guardrails) <a class="header-anchor" href="#_3-엔터프라이즈-안전장치-security-guardrails" aria-label="Permalink to “3. 엔터프라이즈 안전장치 (Security Guardrails)”">​</a></h2><h3 id="_1-상용-prod-배포-2단계-인증-2fa-otp" tabindex="-1">1) 상용(Prod) 배포 2단계 인증 (2FA / OTP) <a class="header-anchor" href="#_1-상용-prod-배포-2단계-인증-2fa-otp" aria-label="Permalink to “1) 상용(Prod) 배포 2단계 인증 (2FA / OTP)”">​</a></h3><p>중요 시스템의 상용 배포 승인 시, 인가된 시스템 아키텍트의 모바일 OTP 또는 사내 SSO 2단계 인증을 거쳐야만 배포 파이프라인이 실행됩니다.</p><h3 id="_2-ddl-파괴적-변경-차단-정책-anti-destructive-ddl-guard" tabindex="-1">2) DDL 파괴적 변경 차단 정책 (Anti-Destructive DDL Guard) <a class="header-anchor" href="#_2-ddl-파괴적-변경-차단-정책-anti-destructive-ddl-guard" aria-label="Permalink to “2) DDL 파괴적 변경 차단 정책 (Anti-Destructive DDL Guard)”">​</a></h3><p><code>DROP TABLE</code>, <code>DROP COLUMN</code>, 대규모 <code>TRUNCATE</code> 등 데이터 유실 위험이 있는 DDL은 AI가 생성할 수 없도록 사전에 차단되어 있습니다. 필요한 경우 &#39;소프트 삭제(Soft Delete)&#39; 또는 &#39;Deprecation 플래그&#39; 방식으로 대체 제안됩니다.</p><h3 id="_3-전사-비상-전체-정지-emergency-kill-switch" tabindex="-1">3) 전사 비상 전체 정지 (Emergency Kill-Switch) <a class="header-anchor" href="#_3-전사-비상-전체-정지-emergency-kill-switch" aria-label="Permalink to “3) 전사 비상 전체 정지 (Emergency Kill-Switch)”">​</a></h3><p>시스템 이상 징후나 비정상 동작이 감지될 경우, 대시보드의 <strong>[Kill-Switch]</strong>를 작동시키면 가동 중인 모든 에이전트의 작업이 즉각 안전하게 중단(Safe Halt)되고 커넥션이 격리됩니다.</p>',9))])}const y=i(A,[["render",D]]);export{m as __pageData,y as default};
